import{_ as s,o as i,c as a,a6 as t}from"./chunks/framework.BBdhcoHf.js";const k=JSON.parse('{"title":"ADR-018: Daemon Built-in Capabilities and $sideband/* Namespace","description":"","frontmatter":{},"headers":[],"relativePath":"adr/018-daemon-capabilities.md","filePath":"adr/018-daemon-capabilities.md","lastUpdated":1772916561000}'),n={name:"adr/018-daemon-capabilities.md"};function r(o,e,d,c,l,p){return i(),a("div",null,[...e[0]||(e[0]=[t(`<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /adr/018-daemon-capabilities.md for this page in Markdown format</div><h1 id="adr-018-daemon-built-in-capabilities-and-sideband-namespace" tabindex="-1">ADR-018: Daemon Built-in Capabilities and <code>$sideband/*</code> Namespace <a class="header-anchor" href="#adr-018-daemon-built-in-capabilities-and-sideband-namespace" aria-label="Permalink to “ADR-018: Daemon Built-in Capabilities and $sideband/* Namespace”">​</a></h1><ul><li><strong>Date</strong>: 2026-03-07</li><li><strong>Status</strong>: Accepted</li><li><strong>Affects</strong>: SDK, CLI</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The connect page needs something meaningful to render when a peer connects. Before this PR the daemon had only two methods (<code>$sideband/echo</code>, <code>$sideband/info</code>) with no introspection surface and no way for a UI to discover what a daemon can do. Three design questions arose:</p><ol><li><strong>How should a UI discover which RPC methods exist?</strong> — enumerating all handlers vs. a dedicated introspection protocol.</li><li><strong>How should user-facing features (stats, future file browser) be advertised?</strong> — a free-form capability bag vs. a fixed schema.</li><li><strong>Where does method introspection belong in the SDK?</strong> — a separate introspection API vs. a method on <code>RpcInterface</code>.</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="_1-sideband-—-reserved-namespace-for-platform-provided-handlers" tabindex="-1">1. <code>$sideband/*</code> — reserved namespace for platform-provided handlers <a class="header-anchor" href="#_1-sideband-—-reserved-namespace-for-platform-provided-handlers" aria-label="Permalink to “1. $sideband/* — reserved namespace for platform-provided handlers”">​</a></h3><p>All handlers registered by the Sideband platform (CLI built-ins, SDK infrastructure) use the <code>$sideband/</code> prefix. User-registered methods MUST NOT use this prefix.</p><p>This makes the platform surface unambiguous and lets UIs apply consistent treatment (e.g., grouping, filtering) without heuristics.</p><h3 id="_2-two-tier-introspection-infrastructure-vs-capabilities" tabindex="-1">2. Two-tier introspection: infrastructure vs. capabilities <a class="header-anchor" href="#_2-two-tier-introspection-infrastructure-vs-capabilities" aria-label="Permalink to “2. Two-tier introspection: infrastructure vs. capabilities”">​</a></h3><p><strong>Infrastructure handlers</strong> (<code>$sideband/rpc.list</code>, <code>$sideband/rpc.describe</code>) are always available on every daemon, CLI or programmatic. They are universal and are NOT listed in <code>capabilities</code> — their presence is implicit.</p><p><strong>Capabilities</strong> (<code>stats</code>, future <code>fs</code>) represent user-facing functional areas that may or may not be present. They are advertised explicitly in <code>$sideband/info</code>:</p><div class="language-typescript"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// $sideband/info response</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  daemonId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: string;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: string;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: string;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  capabilities</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: Record</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">string, object</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// { stats: {}, fs: { root, write } … }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The key design invariant: <strong><code>rpc.list</code> is the truth; <code>rpc.describe</code> is optional display metadata; <code>capabilities</code> is the user-feature contract.</strong></p><p>Rationale for the separation:</p><ul><li><code>rpc.list</code> returns all registered methods — including user-defined ones. The UI uses it for the full method set.</li><li><code>capabilities</code> is a curated, stable API for feature detection. A UI checking <code>capabilities.stats</code> is more robust than checking whether <code>$sideband/stats</code> appears in <code>rpc.list</code>.</li><li><code>rpc.describe</code> is sparse metadata for human display. It is intentionally not filtered against <code>rpc.list</code> — undescribed methods appear in <code>rpc.list</code> but not in <code>rpc.describe</code>, which is correct and expected.</li></ul><h3 id="_3-listmethods-on-rpcinterface" tabindex="-1">3. <code>listMethods()</code> on <code>RpcInterface</code> <a class="header-anchor" href="#_3-listmethods-on-rpcinterface" aria-label="Permalink to “3. listMethods() on RpcInterface”">​</a></h3><p>Method introspection is placed on <code>RpcInterface</code> rather than a separate API:</p><div class="language-typescript"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">interface</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> RpcInterface</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  listMethods</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[]; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Returns registered handler names, sorted lexicographically.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Rationale:</strong> <code>$sideband/rpc.list</code> must work for every daemon — CLI and programmatic. Placing <code>listMethods()</code> on <code>RpcInterface</code> means any daemon, regardless of how it was created, exposes the same introspection surface. A separate top-level introspection API would require daemon authors to opt in explicitly; an <code>RpcInterface</code> method is always there.</p><h3 id="_4-stats-subscriptions-are-session-scoped" tabindex="-1">4. Stats subscriptions are session-scoped <a class="header-anchor" href="#_4-stats-subscriptions-are-session-scoped" aria-label="Permalink to “4. Stats subscriptions are session-scoped”">​</a></h3><p><code>$sideband/stats.start</code> subscriptions are not resumed across reconnects. The client must call <code>stats.start</code> again after a new session is established. Rationale: resuming a subscription requires the daemon to track per-client state across sessions, which adds complexity and creates implicit cleanup obligations. Explicit restart is simpler, predictable, and keeps the daemon stateless between sessions.</p><h2 id="invariants" tabindex="-1">Invariants <a class="header-anchor" href="#invariants" aria-label="Permalink to “Invariants”">​</a></h2><ul><li><code>$sideband/*</code> prefix is reserved for platform use. User handlers MUST NOT use it.</li><li><code>rpc.list</code> and <code>rpc.describe</code> MUST NOT appear in <code>capabilities</code>.</li><li><code>listMethods()</code> returns a sorted array — clients may rely on lexicographic order for stable display.</li><li>Stats subscriptions are terminal at session end — not resumed on reconnect.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>UI can use <code>capabilities</code> for feature detection and <code>rpc.list</code> + <code>rpc.describe</code> for the RPC explorer.</li><li>New CLI capabilities (e.g., <code>fs</code>) follow the same pattern: register handlers, return <code>{ fs: &lt;descriptor&gt; }</code> from the handler registrar, merge into <code>$sideband/info</code>.</li><li>Programmatic daemons that want <code>rpc.list</code> to work correctly call <code>registerRpcMeta()</code> themselves; it is opt-in, not automatic.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li>ADR-013: Peer SDK Core Design Decisions</li><li><code>packages/cli/src/handlers/rpc-meta.ts</code> — <code>registerRpcMeta()</code></li><li><code>packages/cli/src/handlers/stats.ts</code> — <code>registerStatsHandlers()</code></li><li><code>packages/peer/src/types.ts</code> — <code>RpcInterface.listMethods()</code></li></ul>`,29)])])}const g=s(n,[["render",r]]);export{k as __pageData,g as default};
